contract InvMutTest {
    C c;
    IERC20 token;

    constructor(C _c) {
        c = _c;
        token = c.stakingToken();
    }

    // single public function implementing the property-based test
    function run(address staker, uint256 approveAmount, uint256 stakeAmount) public payable {
        // ensure sensible approvals and amounts
        require(staker != address(0), true);

        // The InvMutTest contract is the deployer of c; msg.sender for c calls will be this contract.
        // We simulate the staker by using the public token approve mechanism: the test contract
        // first transfers tokens from staker to itself if possible. However we cannot force an arbitrary
        // external account to transfer tokens; instead we require that staker has approved this contract
        // for at least approveAmount and that approveAmount >= stakeAmount. This is expressed by
        // attempting a safeTransferFrom and catching revert to know if stake will succeed.

        // Read-before values
        uint256 totalBefore = c.totalSupply();
        uint256 balBefore = c.balanceOf(staker);

        // Try to perform stakeFor on behalf of staker by calling stakeFor(staker, stakeAmount) as this contract.
        // According to C, stakeFor uses stakingToken.safeTransferFrom(msg.sender, address(this), _amount)
        // so msg.sender must have allowance and balance. Here msg.sender is this InvMutTest contract.
        // To make stake succeed deterministically in some cases, first attempt to pull tokens from staker
        // into this contract so we can then approve c to pull them. We'll try-catch the transferFrom.

        bool pullSucceeded = false;
        try token.transferFrom(staker, address(this), stakeAmount) returns (bool t) {
            pullSucceeded = t;
        } catch {
            pullSucceeded = false;
        }

        // If pullSucceeded, we hold tokens and can approve c to pull them from this contract and then call stakeFor.
        if (pullSucceeded) {
            // approve c to transfer tokens from this contract
            try token.approve(address(c), stakeAmount) returns (bool ok) {
                // proceed
            } catch {
                // if approve reverts, cannot proceed
            }
        }

        bool stakeReverted = false;
        // Now attempt to call stakeFor(staker, stakeAmount). According to contract, caller must have transferred tokens from msg.sender to c.
        // For cases where the above pullSucceeded and we approved c, stakeFor will still try to transferFrom(msg.sender, address(this), _amount)
        // where msg.sender is this test contract, so token.transferFrom(this, c, amount) should succeed because we approved c.
        try c.stakeFor(staker, stakeAmount) {
            stakeReverted = false;
        } catch {
            stakeReverted = true;
        }

        uint256 totalAfter = c.totalSupply();
        uint256 balAfter = c.balanceOf(staker);

        // General rule to assert:
        // - If stakeReverted is true then either stakeAmount == 0 or the token transfer/approve preconditions failed.
        //   We assert: stakeReverted implies stakeAmount == 0 || totalAfter == totalBefore && balAfter == balBefore
        // - If stakeReverted is false then stakeAmount > 0 and totalAfter == totalBefore + stakeAmount and balAfter == balBefore + stakeAmount
        assert(
            (stakeReverted && (stakeAmount == 0 || (totalAfter == totalBefore && balAfter == balBefore))) ||
            (!stakeReverted && stakeAmount > 0 && totalAfter == totalBefore + stakeAmount && balAfter == balBefore + stakeAmount)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    IERC20 token;

    constructor(C _c) {
        c = _c;
        token = c.stakingToken();
    }

    // single public function implementing the property-based test
    function run(address staker, uint256 stakeAmount) public payable {
        // staker must be non-zero to observe its balance in c
        require(staker != address(0));

        // Read-before values
        uint256 totalBefore = c.totalSupply();
        uint256 balBefore = c.balanceOf(staker);

        // Attempt to prepare funds: try to pull tokens from staker into this contract so we can approve c.
        bool pullSucceeded = false;
        // We try a low-level call to token.transferFrom(staker, address(this), stakeAmount) and detect success.
        // Using try/catch on IERC20 may fail for tokens that don't return bool; so use low-level call via address(token).
        if (stakeAmount > 0) {
            (bool ok, bytes memory ret) = address(token).call(
                abi.encodeWithSelector(token.transferFrom.selector, staker, address(this), stakeAmount)
            );
            // Consider success when call returned true or returned no data but succeeded.
            if (ok) {
                if (ret.length == 0) {
                    // Some tokens don't return bool but succeeded
                    pullSucceeded = true;
                } else {
                    // decode returned bool
                    try this.decodeBool(ret) returns (bool b) {
                        if (b) pullSucceeded = true;
                    } catch {
                        pullSucceeded = false;
                    }
                }
            } else {
                pullSucceeded = false;
            }
        }

        // If we pulled tokens to this contract, approve c to pull them
        if (pullSucceeded) {
            // attempt to approve c to spend stakeAmount from this contract
            (bool okA, bytes memory retA) = address(token).call(
                abi.encodeWithSelector(token.approve.selector, address(c), stakeAmount)
            );
            // If approve failed, mark pullSucceeded false so we don't expect stake to succeed
            if (!okA) pullSucceeded = false;
            else if (retA.length > 0) {
                try this.decodeBool(retA) returns (bool b) {
                    if (!b) pullSucceeded = false;
                } catch {
                    pullSucceeded = false;
                }
            }
        }

        // Now attempt the stakeFor call and record whether it reverted
        bool stakeReverted = false;
        try c.stakeFor(staker, stakeAmount) {
            stakeReverted = false;
        } catch {
            stakeReverted = true;
        }

        uint256 totalAfter = c.totalSupply();
        uint256 balAfter = c.balanceOf(staker);

        // General rule to assert:
        // If stakeReverted then the state observed in c did not change for totalSupply and the staker's balance.
        // If stake did not revert then stakeAmount must be > 0 and both totalSupply and staker balance increased by exactly stakeAmount.
        assert(
            (stakeReverted && totalAfter == totalBefore && balAfter == balBefore) ||
            (!stakeReverted && stakeAmount > 0 && totalAfter == totalBefore + stakeAmount && balAfter == balBefore + stakeAmount)
        );
    }

    // helper to decode returned bool from low-level calls
    function decodeBool(bytes memory b) public pure returns (bool) {
        require(b.length >= 32);
        uint256 v;
        assembly { v := mload(add(b, 32)) }
        return v != 0;
    }

    receive() external payable {}
}

