contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test entry
    function run(address staker, uint256 amount) public payable {
        require(amount > 0, "need positive amount");
        // Ensure this contract has enough of the staking token to transferFrom: caller must have approved this contract
        // We cannot mint tokens here; instead we observe behaviour when stakeFor is called by this test contract as msg.sender for token transferFrom.
        // Record before values
        uint256 beforeTotal = c.totalSupply();
        uint256 beforeBalance = c.balanceOf(staker);

        bool reverted = false;
        // perform the state-changing call. It will try to transferFrom msg.sender to c; msg.sender here is this test contract.
        // As required by the template, make the call a top-level statement and capture revert via try/catch.
        try c.stakeFor(staker, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterTotal = c.totalSupply();
        uint256 afterBalance = c.balanceOf(staker);

        // General rule: if the call did not revert then totalSupply and staker balance increased by exactly amount;
        // if it reverted then state must be unchanged (no partial application) — i.e., totals and balances equal before values.
        assert( (!reverted && afterTotal == beforeTotal + amount && afterBalance == beforeBalance + amount)
                || (reverted && afterTotal == beforeTotal && afterBalance == beforeBalance) );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test entry
    // _rewardsToken: token to notify rewards for
    // _amount: amount to notify (must be > 0 for nominal success)
    // distributor: address that will be used as msg.sender when calling notifyRewardAmount (must match c.rewardDistributor() to avoid immediate revert)
    function run(address _rewardsToken, uint256 _amount, address distributor) public payable {
        require(_rewardsToken != address(0));
        // read observable before-values
        uint256 beforeTotal = c.totalSupply();
        uint40 beforePeriodFinish = c.rewardPeriodFinish(_rewardsToken);
        address beforeDistributor = c.rewardDistributor();

        bool reverted = false;
        // We must call notifyRewardAmount as the distributor; since the checker will call run only once and msg.sender for c calls is this contract,
        // we simulate being the distributor by requiring the provided distributor matches the contract's configured distributor and then
        // calling through c.notifyRewardAmount directly — the contract checks msg.sender == rewardDistributor, so the call will succeed only if
        // this InvMutTest contract is the configured distributor. To satisfy the requirement that we only use c's public API, we pass through.
        // If distributor does not equal address(this) then the call will revert with "not distributor"; the general rule below accounts for that.
        // Make the state-changing call as a top-level statement and capture revert via try/catch.
        try c.notifyRewardAmount(_rewardsToken, _amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterTotal = c.totalSupply();
        uint40 afterPeriodFinish = c.rewardPeriodFinish(_rewardsToken);
        address afterDistributor = c.rewardDistributor();

        // General rule:
        // - If the call did not revert then totalSupply is unchanged (notifyRewardAmount should not alter staking totals),
        //   and periodFinish for the token is strictly greater than or equal to beforePeriodFinish (it advances to >= now),
        //   and distributor address is unchanged.
        // - If the call reverted then observable state (totalSupply, periodFinish, distributor) remains equal to before-values.
        // This ensures notifyRewardAmount either fully applies its reward update or reverts leaving observable state intact.
        assert(
            (!reverted && afterTotal == beforeTotal && afterDistributor == beforeDistributor && uint256(afterPeriodFinish) >= uint256(beforePeriodFinish))
            || (reverted && afterTotal == beforeTotal && afterDistributor == beforeDistributor && afterPeriodFinish == beforePeriodFinish)
        );
    }

    // receive to accept any Ether if needed by calls (not used here)
    receive() external payable {}
}

contract InvMutTest {
