    function run(address _rewardsToken, uint256 _amount, address /*distributor param kept for API symmetry*/) public payable {
        require(_rewardsToken != address(0));

        // observe before-values through public getters
        uint256 beforeTotal = c.totalSupply();
        uint40 beforePeriodFinish = c.rewardPeriodFinish(_rewardsToken);
        address beforeDistributor = c.rewardDistributor();

        bool reverted = false;
        // call the state-changing function at top-level and capture revert
        try c.notifyRewardAmount(_rewardsToken, _amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe after-values
        uint256 afterTotal = c.totalSupply();
        uint40 afterPeriodFinish = c.rewardPeriodFinish(_rewardsToken);
        address afterDistributor = c.rewardDistributor();

        // General invariant:
        // - notifyRewardAmount must not change totalSupply or rewardDistributor in any case
        // - if it succeeds then the token's periodFinish must advance to >= previous value
        // - if it reverts then periodFinish remains equal to previous
        assert(
            afterTotal == beforeTotal && afterDistributor == beforeDistributor && (
                (!reverted && uint256(afterPeriodFinish) >= uint256(beforePeriodFinish)) || (reverted && afterPeriodFinish == beforePeriodFinish)
            )
        );
    }

    receive() external payable {}
}

