contract InvMutTest {
    C c;
    IERC20 token;

    constructor(C _c) {
        c = _c;
        token = c.stakingToken();
    }

    // params: from is the caller who will be asked to transferFrom (msg.sender of stakeFor),
    // but in this harness all calls into c originate from this contract. So we parametrize
    // 'amount' and 'fromBalance' to arrange token.balanceOf(this) and simulate approvals
    // by relying on ERC20 transferFrom call outcome. We cannot manipulate external ERC20 here,
    // but we can still assert the general relation when stakeFor does not revert: that totalSupply
    // and balanceOf(beneficiary) increase by amount.

    function run(address beneficiary, uint256 amount) public payable {
        require(beneficiary != address(0));

        // record before values
        uint256 beforeTotal = c.totalSupply();
        uint256 beforeBal = c.balanceOf(beneficiary);

        bool reverted;
        // attempt to call stakeFor(beneficiary, amount) from this contract
        // stakeFor will call stakingToken.safeTransferFrom(msg.sender, address(this), _amount);
        // which may revert; we capture that.
        try c.stakeFor(beneficiary, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterTotal = c.totalSupply();
        uint256 afterBal = c.balanceOf(beneficiary);

        // If the call did NOT revert, then totalSupply and beneficiary balance must have increased by exactly amount.
        // If it DID revert, we cannot assume any state change; so assert that either reverted is true, or the relation holds.
        assert(reverted || (afterTotal == beforeTotal + amount && afterBal == beforeBal + amount));
    }

    receive() external payable {}
}

