contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public function containing the whole test
    function run(address beneficiary, uint256 amount) public payable {
        // require a valid beneficiary to avoid trivial zero-address edge
        require(beneficiary != address(0));

        // observe before-values using only public interface
