contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public entry performing the property check
    function run(address staker, uint256 amount, bool claim) public payable {
        require(staker != address(0));

        // Capture before-observations
        uint256 beforeTotal = c.totalSupply();
        uint256 beforeBalance = c.balanceOf(staker);

        // Attempt withdraw as the staker by calling migrateWithdraw path is restricted to migrator
        // We must call withdraw on behalf of staker. Since msg.sender for calls from this contract
        // is this contract, we simulate staker by calling stake/withdraw flows only as this contract.
        // To make sure there is something to withdraw, if the provided staker equals address(this),
        // we can stake some tokens only if stakingToken allows it. However we cannot mint tokens here.
        // Therefore the test will exercise general property about effects: try calling withdraw and
        // observe whether totalSupply and balance changed consistently with success or revert.

        bool reverted;
        try c.withdraw(amount, claim) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterTotal = c.totalSupply();
        uint256 afterBalance = c.balanceOf(staker);

        // If withdraw succeeded (didn't revert) then the totalSupply decreased by at most amount
        // and the specific staker's balance decreased by at most amount, and the decreases are equal
        // (since withdraw reduces both by same amount for the staker). If it reverted, neither changed.
        // We express a general invariant: either reverted implies no change; or if not reverted then
        // (beforeTotal - afterTotal) == (beforeBalance - afterBalance) and both are <= amount.

        assert(
            (reverted && beforeTotal == afterTotal && beforeBalance == afterBalance) ||
            (!reverted && (beforeTotal >= afterTotal) && (beforeBalance >= afterBalance) &&
                (beforeTotal - afterTotal) == (beforeBalance - afterBalance) &&
                (beforeTotal - afterTotal) <= amount)
        );
    }

    receive() external payable {}
}

