    // We test the property for notifyRewardAmount: when called by rewardDistributor with a positive amount
    // it must update rewardData and transfer the amount into the contract. The test calls c.notifyRewardAmount
    // and asserts that either the call reverted OR the contract's balance of the reward token increased by at
    // most the notified amount (equal to the amount transferred). Because we cannot read internal rewardData
    // directly, we observe address(c).balance of the reward token and the returned rewardPeriodFinish.

    function run(address rewardToken, address distributor, uint256 amount) public payable {
        // Preconditions: amount > 0 as required by notifyRewardAmount, and rewardToken must have been added by owner.
        // We cannot ensure addReward has been called here, so allow both possibilities: either call reverts (not distributor or unknown token)
        // or it succeeds. To enable transferring tokens from distributor, this test assumes the distributor has approved
        // this contract for the token; since we cannot set up external token balances or approvals here, many inputs will revert — that's acceptable.
        require(amount > 0, true);

        // Read pre-state: token balance of c and periodFinish for the token (may be zero if unknown)
        uint256 beforeBalance;
        uint40 beforeFinish;
        // To read ERC20 balance we use IERC20 interface via low-level static call through C's public getters: we are allowed to call external contracts directly.
        // But constraints require observing c only via its public surface. We may call IERC20(rewardToken).balanceOf(address(c)).
        beforeBalance = IERC20(rewardToken).balanceOf(address(c));
        // rewardPeriodFinish is a public view on C
        beforeFinish = c.rewardPeriodFinish(rewardToken);

        bool reverted;
        // The contract's notifyRewardAmount requires msg.sender == rewardDistributor. We cannot change c's storage here, but we can try to call
        // notifyRewardAmount and let it revert if msg.sender != distributor. However the test contract must call c.notifyRewardAmount; msg.sender will be this test contract.
        // To simulate being the distributor, the test cannot change msg.sender. So we call regardless; if msg.sender != rewardDistributor it will revert.
        try c.notifyRewardAmount(rewardToken, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read post-state
        uint256 afterBalance = IERC20(rewardToken).balanceOf(address(c));
        uint40 afterFinish = c.rewardPeriodFinish(rewardToken);

        // General rule: if the call succeeded (not reverted) then the contract's token balance must have increased by exactly amount
        // (notifyRewardAmount transfers _amount from msg.sender to the contract), and periodFinish must be >= beforeFinish and > 0.
        // If the call reverted, no condition on state is required. Expressed as a single assert:
        assert(reverted || (afterBalance >= beforeBalance && afterBalance - beforeBalance == amount && afterFinish >= beforeFinish && afterFinish != uint40(0)));
    }

    // Minimal IERC20 interface for balanceOf
    receive() external payable {}
}

