        // The test harness provides a fresh C where msg.sender is this contract; we cannot mint tokens here.
        // Instead, we only interact through c assuming transferFrom will revert if not approved; we still can call stakeFor which will revert if transferFrom fails.

        // Record before values
        uint256 totalBefore = c.totalSupply();
        uint256 balBefore = stakingToken.balanceOf(address(c));

        // Try to perform stakeFor: call stakeFor from this contract using c.stakeFor(staker, stakeAmount) will attempt transferFrom(msg.sender,..)
        bool stakeReverted;
        try c.stakeFor(staker, stakeAmount) {
            stakeReverted = false;
        } catch {
            stakeReverted = true;
        }

        // Read totals after attempted stake
        uint256 totalAfterStake = c.totalSupply();
        uint256 balAfterStake = stakingToken.balanceOf(address(c));

        // Now attempt withdraw as the staker: we need to simulate calls from staker. The checker runs run(...) with msg.sender being this contract, so we cannot impersonate staker.
        // But we can call c.withdraw(amount, claim) which will act for msg.sender (this contract). To model a withdraw attempt, if stake succeeded and staker == address(this), withdraw may proceed.
        // Ensure we only call withdraw when staker == address(this) to actually affect c state.

        bool withdrawReverted;
        uint256 totalAfterWithdraw;
        uint256 balAfterWithdraw;

        if (staker == address(this)) {
            // Only meaningful if stake succeeded and stake was for this contract
            try c.withdraw(amount, claim) {
                withdrawReverted = false;
            } catch {
                withdrawReverted = true;
            }
            totalAfterWithdraw = c.totalSupply();
            balAfterWithdraw = stakingToken.balanceOf(address(c));
        } else {
            // If invoking withdraw as another staker would be irrelevant; record current values
            withdrawReverted = true; // mark as not-executed for the purposes of the assertion below
            totalAfterWithdraw = totalAfterStake;
            balAfterWithdraw = balAfterStake;
        }

        // General rule to assert:
        // 1) totalSupply never increases from its previous value after stake attempt or withdraw: totalAfterWithdraw <= totalBefore + (stakeAmount if stake succeeded and was for this contract)
        // But to keep formula general and only use public reads, assert that withdraw does not increase totalSupply and if withdraw succeeded then it decreases by exactly min(amount, previous balanceOf(this)).

        // compute expected decrease when withdraw succeeds: previous balance of this contract in c before withdraw equals c.balanceOf(address(this)) readable
        uint256 balOfThisBeforeWithdraw = c.balanceOf(address(this));

        if (!withdrawReverted) {
            // If withdraw succeeded, totalAfterWithdraw should be totalBeforeWithdraw - actualWithdrawn
            // actualWithdrawn equals the change in stakingToken balance of c (balAfterWithdraw <= balBefore) but other transfers may also happen; however stakingToken.safeTransfer is called exactly for withdraw amount.
            // So require totalAfterWithdraw + amount == totalBeforeWithdraw, but totalBeforeWithdraw should be totalAfterStake here.
            // Use observable values: totalAfterStake is the supply before withdraw.
            assert(totalAfterWithdraw + amount == totalAfterStake);
        } else {
            // If withdraw reverted (or not performed), ensure totalSupply did not increase compared to before any operation
            assert(totalAfterWithdraw <= totalBefore + stakeAmount);
        }
    }

    receive() external payable {}
}

