        uint256 balBefore = c.balanceOf(staker);

        // Try to perform withdraw as if called by staker: since run() executes as this contract,
        // we need to simulate withdraw being invoked by staker via the migrator mechanism is not available.
        // However the problem statement guarantees msg.sender for calls on c is this contract
        // so we will only call withdraw when staker == address(this) to model a real withdraw.
        // If staker != address(this) we expect the call to revert because balances won't match.

        bool reverted;
        if (staker == address(this)) {
            // require this contract has enough staked balance to attempt withdraw if amount>0
            // But we cannot read internal stakingToken balances here to top-up; the call may revert.
            try c.withdraw(amount, claim) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // calling withdraw through a low-level mechanism to set msg.sender to staker is impossible here,
            // so we call a view to ensure we still reach the assert. We'll attempt withdraw and expect revert.
            try c.withdraw(amount, claim) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // Read post-state
        uint256 totalAfter = c.totalSupply();
        uint256 balAfter = c.balanceOf(staker);

        // General rule to assert:
        // If the withdraw did NOT revert then:
        //   - totalSupply must be <= totalBefore (it never increases), and
        //   - the staker's balance must have decreased by exactly `amount`.
        // If the withdraw reverted then we cannot assume state changed; assert a relation that holds in both cases.
        if (!reverted) {
            // assert totalSupply did not increase and balance decreased by amount
            assert(totalAfter <= totalBefore && balBefore >= balAfter && balBefore - balAfter == amount);
        } else {
            // when reverted, no guarantee on state change from this test's perspective, but ensure at least
            // that either the attempted action was invalid (amount == 0 or balBefore < amount) which are the contract's require conditions
            // or totalSupply did not increase (withdraw should not increase supply even on revert)
            assert(totalAfter <= totalBefore || amount == 0 || balBefore < amount);
        }
    }

    receive() external payable {}
}

