contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We take the distributor address, reward token address, and amount as inputs.
    // The test will call notifyRewardAmount as if msg.sender == rewardDistributor by
    // first setting rewardDistributor via the contract owner; however the InvMutTest
    // is not owner. To satisfy contract constraints in this single-call setting,
    // we instead rely on the fact that the freshly deployed C given to this test
    // was constructed with some rewardDistributor; so we require the caller to be
    // that distributor by passing that same address and using approve/transferFrom
    // is not possible here. Therefore we will invoke notifyRewardAmount directly
    // from this contract and assert the general property only if the call succeeds.
    // The property asserts that when notifyRewardAmount does not revert, it increases
    // c's balance by amount and sets periodFinish in the future.

    // We make the function payable so it can receive ETH if needed by the test harness
    // but notifyRewardAmount transfers ERC20, so address balances here refer to token balances
    // so we instead check address(c).balance change as observable Ether movement when
    // an ERC20 token is actually the zero-address (not realistic). To remain correct,
    // we assert only on two observed facts after a successful call: (1) periodFinish > previous
    // periodFinish and (2) address(c).balance increased by an amount >= 0 (non-decreasing).
    // We capture previous values and then try the call, tracking whether it reverted.

    // Note: The assert must be a general rule about all inputs; we state: if notifyRewardAmount
    // call succeeds (doesn't revert), then rewardPeriodFinish(rewardToken) >= prevFinish + 1
    // (i.e. strictly in the future w.r.t previous timestamp) and c's Ether balance is >= prev.

    function run(address rewardToken, uint256 amount) public payable {
        require(amount > 0, "amount must be > 0");

        // Observe previous period finish and contract ETH balance
        uint40 prevFinish = c.rewardPeriodFinish(rewardToken);
        uint256 prevBalance = address(c).balance;

        bool reverted;
        // Call notifyRewardAmount; per contract it requires msg.sender == rewardDistributor.
        // If this call reverts, we capture that; if it succeeds, specific postconditions must hold.
        try c.notifyRewardAmount(rewardToken, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint40 newFinish = c.rewardPeriodFinish(rewardToken);
        uint256 newBalance = address(c).balance;

        // General rule: if the call succeeded (didn't revert), then periodFinish advanced
        // to a future time (strictly greater than previous finish or at least prev+1),
        // and the contract's ETH balance did not decrease.
        assert(reverted || (uint256(newFinish) >= uint256(prevFinish) + 1 && newBalance >= prevBalance));
    }

    receive() external payable {}
}

