        uint256 beforeTokenBalCaller = staking.balanceOf(caller);

        // perform the state-changing call as a top-level statement with revert capture
        bool reverted;
        try c.withdraw(amount, claim) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe post-state
        uint256 afterTotal = c.totalSupply();
        uint256 afterBal = c.balanceOf(caller);
        uint256 afterTokenBalCaller = staking.balanceOf(caller);

        // single general assert as specified
        assert(
            reverted
                ? (afterTotal == beforeTotal && afterBal == beforeBal && afterTokenBalCaller == beforeTokenBalCaller)
                : (beforeTotal == afterTotal + amount && beforeBal == afterBal + amount && afterTokenBalCaller == beforeTokenBalCaller + amount)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // params: distributor will call notifyRewardAmount, owner must have added the reward token beforehand
    // We take addresses for owner, distributor, rewardToken and amounts; this contract is the caller of c.notifyRewardAmount
    function run(address owner, address distributor, address rewardToken, uint256 addAmount, uint256 notifyAmount) public payable {
        require(owner != address(0) && distributor != address(0) && rewardToken != address(0), true);

        // Step 1: owner must add rewardToken. Only owner can call addReward. The test contract cannot become owner, so we simulate by assuming deployer of c was owner.
        // We cannot call addReward since only owner can; instead we check rewardData.lastUpdateTime via rewardPeriodFinish to see if token is known.
        // If token is unknown, notifyRewardAmount should revert with "unknown reward token" regardless of caller.

        // Record pre-call balance of rewardToken held by c
        uint256 beforeBalance = IERC20(rewardToken).balanceOf(address(c));

        // Record distributor configured in c
        address configuredDistributor = c.rewardDistributor();

        // We will attempt to call notifyRewardAmount as this contract. The contract must hold tokens to transfer; ensure balance is sufficient if this contract is caller.
        // Transfer notifyAmount of rewardToken to this contract if possible: we cannot mint tokens; assume token has balance at this address in the environment isn't guaranteed.
        // To avoid requiring token transfer, we will not depend on successful transfer; instead we observe whether the call reverted and the resulting c balance.

        bool reverted;
        try c.notifyRewardAmount(rewardToken, notifyAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterBalance = IERC20(rewardToken).balanceOf(address(c));

        // General rule: If notifyRewardAmount call did not revert, then msg.sender must equal configured distributor, notifyAmount>0, token must have been added (rewardPeriodFinish != 0), and c's balance increased by at least notifyAmount.
        // If it reverted, then at least one of those conditions is false.

        bool tokenKnown = (c.rewardPeriodFinish(rewardToken) != 0);
        bool callerIsDistributor = (configuredDistributor == address(this));
        bool amountPositive = (notifyAmount > 0);

        // Formulate the iff style: not reverted implies all good and balance increased by >= notifyAmount
        // reverted implies at least one precondition fails OR balance did not increase by >= notifyAmount

        assert((!reverted) == (callerIsDistributor && amountPositive && tokenKnown && afterBalance >= beforeBalance + notifyAmount));
    }

    receive() external payable {}
 }

